<?php
namespace App\Http\Controllers;
use App\Models\Floor;use App\Models\FloorPlan;use App\Services\FloorPlanCalibrationService;use App\Support\PersistentStorage;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\ValidationException;
class FloorPlanController extends Controller {
 public function store(Request $r,Floor $floor):JsonResponse{abort_unless($r->user()->can('locations.manage'),403);$d=$r->validate(['floor_plan'=>'required|file|mimes:png,jpg,jpeg,pdf|max:20480']);$f=$d['floor_plan'];$disk=PersistentStorage::diskName();$path=$f->store("floor-plans/{$floor->id}",$disk);if($path===false)throw ValidationException::withMessages(['floor_plan'=>'The floor plan could not be stored.']);$dimensions=null;if(str_starts_with((string)$f->getMimeType(),'image/'))$dimensions=@getimagesize($f->getRealPath());$plan=DB::transaction(function()use($r,$floor,$f,$path,$dimensions,$disk){$floor->floorPlans()->where('is_active',true)->update(['is_active'=>false]);return $floor->floorPlans()->create(['uploaded_by'=>$r->user()->id,'original_name'=>$f->getClientOriginalName(),'file_path'=>$path,'storage_disk'=>$disk,'mime_type'=>$f->getMimeType(),'file_size'=>$f->getSize(),'original_width'=>$dimensions[0]??null,'original_height'=>$dimensions[1]??null,'version'=>($floor->floorPlans()->max('version')??0)+1,'is_active'=>true,'processing_status'=>'ready']);});return response()->json($plan,201);}
 public function file(Request $r,FloorPlan $floorPlan){abort_unless($r->user()->can('dashboard.view'),403);$disk=$floorPlan->storage_disk?:'local';abort_unless(Storage::disk($disk)->exists($floorPlan->file_path),404);return Storage::disk($disk)->response($floorPlan->file_path,$floorPlan->original_name,['Content-Type'=>$floorPlan->mime_type,'Cache-Control'=>'private, max-age=3600']);}
 public function calibrate(Request $r,FloorPlan $floorPlan,FloorPlanCalibrationService $service):JsonResponse{abort_unless($r->user()->can('locations.manage'),403);$d=$r->validate(['x1'=>'required|numeric|between:0,1','y1'=>'required|numeric|between:0,1','x2'=>'required|numeric|between:0,1','y2'=>'required|numeric|between:0,1','distance_metres'=>'required|numeric|min:0.1|max:10000']);try{$plan=$service->calibrate($floorPlan,$d,$r->user()->id);}catch(\InvalidArgumentException $e){throw ValidationException::withMessages(['calibration'=>$e->getMessage()]);}return response()->json($plan);}
 public function boundary(Request $r,FloorPlan $floorPlan):JsonResponse{abort_unless($r->user()->can('locations.manage'),403);$d=$r->validate(['points'=>'required|array|min:3|max:500','points.*.x'=>'required|numeric|between:0,1','points.*.y'=>'required|numeric|between:0,1']);$floorPlan->update(['usable_boundary'=>$d['points']]);return response()->json($floorPlan->refresh());}
 public function activate(Request $r,FloorPlan $floorPlan):JsonResponse{abort_unless($r->user()->can('locations.manage'),403);DB::transaction(function()use($floorPlan){$floorPlan->floor->floorPlans()->update(['is_active'=>false]);$floorPlan->update(['is_active'=>true]);});return response()->json($floorPlan->refresh());}
 public function destroy(Request $r,FloorPlan $floorPlan):JsonResponse{abort_unless($r->user()->can('locations.manage'),403);Storage::disk($floorPlan->storage_disk?:'local')->delete($floorPlan->file_path);$floorPlan->delete();return response()->json(null,204);}
}
